package br.com.helptech.v3;
import android.content.*;import android.app.*;import android.os.*;import android.media.*;import android.net.Uri;
public class AlarmReceiver extends android.content.BroadcastReceiver {
 static final String CHANNEL="helptech_alarm_v32";
 static int request(String id){return id.hashCode() & 0x7fffffff;}
 static void cancel(Context c,String id){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(PendingIntent.getBroadcast(c,request(id),new Intent(c,AlarmReceiver.class).setAction("helptech.alarm."+id),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(request(id));}
 static void set(Context c,String id,String client,String service,String address,long when){Intent i=new Intent(c,AlarmReceiver.class).setAction("helptech.alarm."+id);i.putExtra("id",id);i.putExtra("client",client);i.putExtra("service",service);i.putExtra("address",address);PendingIntent pi=PendingIntent.getBroadcast(c,request(id),i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}
 @Override public void onReceive(Context c,Intent i){String id=i.getStringExtra("id");if(id==null)return;String client=i.getStringExtra("client"),service=i.getStringExtra("service"),address=i.getStringExtra("address");NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);Uri sound=android.provider.Settings.System.DEFAULT_ALARM_ALERT_URI;if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel(CHANNEL,"Alarmes de serviços HELP-TECH",NotificationManager.IMPORTANCE_HIGH);channel.setSound(sound,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());channel.enableVibration(true);nm.createNotificationChannel(channel);}Intent screen=new Intent(c,AlarmActivity.class);screen.putExtras(i);screen.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent full=PendingIntent.getActivity(c,request(id),screen,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("HELP-TECH: "+client).setContentText("Chamado: "+service).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setOngoing(true).setAutoCancel(false).setContentIntent(full).setFullScreenIntent(full,true);nm.notify(request(id),b.build());}
}
